from pathlib import Path
import pandas as pd, json, html
ROOT=Path(__file__).resolve().parents[1]
S=ROOT/'submission'; OUT=S/'dashboard'/'executive_dashboard.html'
d=pd.read_csv(S/'monthly_recovery_metrics.csv')
complete=d[d.month_complete]
raw=json.loads((ROOT/'output'/'preprocessed'/'preprocessing_report.json').read_text(encoding='utf-8'))
summary=json.loads((S/'analysis_summary.json').read_text(encoding='utf-8'))
# Bars scaled within complete months only; August appears separately at reduced, dashed height.
maxval=complete.gross_successful_amount.max()
bar_items=[]
for _,r in d.iterrows():
    val=float(r.gross_successful_amount); h=max(2,int(120*val/maxval)); x=52+len(bar_items)*75
    cls='partial' if not r.month_complete else ''
    mom='—' if pd.isna(r.mom_change_pct) else f"{r.mom_change_pct:+.1f}%"
    bar_items.append(f'<g class="bar {cls}"><rect x="{x}" y="{150-h}" width="42" height="{h}" rx="5"/><text x="{x+21}" y="170" text-anchor="middle">{r.month[-2:]}</text><text class="value" x="{x+21}" y="{143-h}" text-anchor="middle">₹{val/1e7:.1f}Cr</text><text class="mom" x="{x+21}" y="190" text-anchor="middle">{mom}</text></g>')
chart=''.join(bar_items)
exact_removed=sum(t['exact_duplicate_rows_removed_to_quarantine'] for t in raw['tables'].values())
month_rows=''.join(f"<tr><td>{r.month}</td><td>₹{r.gross_successful_amount/1e7:.2f} Cr</td><td>{r.successful_payment_events:,.0f}</td><td>{r.distinct_paying_accounts:,.0f}</td><td>{'Complete' if r.month_complete else '<b>Partial (to Aug 8)</b>'}</td><td>{'—' if pd.isna(r.mom_change_pct) else f'{r.mom_change_pct:+.1f}%'}</td></tr>" for _,r in d.iterrows())
OUT.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Collections recovery | Executive snapshot</title>
<style>
:root{{--ink:#17243a;--muted:#62718a;--line:#dce4ef;--blue:#315eea;--pale:#f3f6fb;--teal:#087e78;--amber:#a56200;--red:#bd3f36}}
*{{box-sizing:border-box}}body{{margin:0;background:#eef2f8;color:var(--ink);font:14px/1.42 Inter,Segoe UI,Arial,sans-serif}}.page{{max-width:1280px;margin:auto;padding:22px 28px}}header{{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:15px}}h1{{font-size:26px;margin:0 0 3px}}.sub{{color:var(--muted)}}.badge{{padding:6px 10px;border-radius:16px;background:#fff1d6;color:#855000;font-weight:700;font-size:12px}}
.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:12px 0}}.card,.panel{{background:white;border:1px solid var(--line);border-radius:12px;padding:15px 17px;box-shadow:0 2px 8px #152b4910}}.label{{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.06em}}.number{{font-size:25px;font-weight:750;margin:6px 0 2px}}.note{{color:var(--muted);font-size:12px}}.grid{{display:grid;grid-template-columns:1.5fr 1fr;gap:12px}}h2{{font-size:16px;margin:0 0 8px}}.chart{{width:100%;height:230px}}.bar rect{{fill:var(--blue)}}.bar.partial rect{{fill:#91a7ef;stroke:var(--blue);stroke-dasharray:4 3}}.bar text{{fill:var(--muted);font-size:11px}}.bar .value{{fill:var(--ink);font-size:10px;font-weight:700}}.bar .mom{{font-size:10px}}.legend{{font-size:11px;color:var(--muted)}}.findings{{display:grid;gap:10px}}.finding{{padding:10px 12px;background:var(--pale);border-radius:8px}}.finding strong{{display:block;margin-bottom:2px}}.good{{color:var(--teal)}}.warn{{color:var(--amber)}}.red{{color:var(--red)}}.table-panel{{margin-top:12px}}table{{border-collapse:collapse;width:100%;font-size:12px}}th,td{{padding:7px 8px;border-bottom:1px solid var(--line);text-align:right}}th:first-child,td:first-child{{text-align:left}}th{{color:var(--muted);font-weight:650}}.foot{{margin-top:10px;color:var(--muted);font-size:11px}}@media(max-width:800px){{.cards{{grid-template-columns:repeat(2,1fr)}}.grid{{grid-template-columns:1fr}}.page{{padding:14px}}}}
</style></head><body><main class="page"><header><div><h1>Collections recovery: executive snapshot</h1><div class="sub">Independent read of recorded payment events · Jan 1–Aug 8, 2026</div></div><div class="badge">AUGUST IS PARTIAL</div></header>
<section class="cards"><div class="card"><div class="label">Recorded SUCCESS cash</div><div class="number">₹{summary['successful_amount_total']/1e7:.2f} Cr</div><div class="note">Jan 1–Aug 8, assuming INR; gross, not net settled</div></div><div class="card"><div class="label">Complete months</div><div class="number">7</div><div class="note">Jan–Jul; dataset is shorter than 12 months</div></div><div class="card"><div class="label">Largest positive complete-month move</div><div class="number good">Mar +{float(d.loc[d.month.eq('2026-03'),'mom_change_pct'].iloc[0]):.1f}%</div><div class="note">One month only; not a sustained trend</div></div><div class="card"><div class="label">Exact duplicate rows removed</div><div class="number">{exact_removed:,}</div><div class="note">Copies retained in quarantine; payment IDs reconciled separately</div></div></section>
<section class="grid"><div class="panel"><h2>Gross successful payments by month</h2><svg class="chart" viewBox="0 0 660 215" role="img" aria-label="Monthly gross successful payment amounts"><line x1="35" y1="150" x2="640" y2="150" stroke="#cbd5e3"/>{chart}</svg><div class="legend">Bars show recorded successful amount. Month-over-month labels compare gross amount. Dashed pale bar is partial August.</div></div>
<div class="panel"><h2>What leadership should take away</h2><div class="findings"><div class="finding"><strong>11% claim: not established as a sustained improvement</strong>March is +11.0%; February, April, and June are down. July is +6.7%. August cannot be compared as a full month.</div><div class="finding"><strong>Recovery rate and causal drivers: not identifiable yet</strong>No historical eligible-account denominator, reliable event timezone, rollout date, or attribution window.</div><div class="finding"><strong>₹10 Cr ROI: insufficient inputs</strong>No channel/agent costs or settlement/reversal linkage. Run a controlled targeting test before committing the full budget.</div></div></div></section>
<section class="panel table-panel"><h2>Monthly evidence</h2><table><thead><tr><th>Month</th><th>Gross cash</th><th>SUCCESS events</th><th>Paying accounts</th><th>Coverage</th><th>MoM</th></tr></thead><tbody>{month_rows}</tbody></table></section>
<div class="foot">Metric: sum of amount for canonical payment IDs labeled SUCCESS. Exact duplicate rows removed; same-ID rows coalesced only when all payment facts match except a missing reference. Currency is inferred from assignment context; payment reversal links are unavailable. Payer counts are descriptive; no eligible-account denominator is established.</div></main></body></html>''',encoding='utf-8')

# Quality report
issues=pd.read_csv(S/'data_quality_issues.csv')
md=['# Data quality report','', 'The source README says the dataset is synthetic and intentionally contains data defects. Raw inputs are preserved. Preprocessing rules and row-level counts are in [preprocessing report](../output/preprocessed/preprocessing_report.md).','', '## Key quantified findings','',
 f"- {exact_removed:,} exact duplicate rows removed to quarantine across the event tables.",
 f"- Payments: {summary['payment_rows_raw']:,} raw rows → {summary['payment_rows_after_exact_dedupe']:,} after exact dedupe → {summary['payment_id_canonical_rows']:,} canonical payment IDs.",
 f"- {summary['payment_id_rows_coalesced']} repeated payment IDs differed only because one copy had a missing reference; the reference was safely coalesced within ID. No other payment-ID conflicts remained.",
 f"- {summary['distinct_payment_references_reused']:,} non-null references are reused across payment IDs; all {summary['reused_references_with_multiple_accounts']:,} repeated references span multiple accounts and different amounts. Reference alone is not a dedupe key.",
 f"- {summary['borrower_id_missing_in_accounts']:,} accounts have no borrower ID. The file has 30,000 account IDs; {summary['successful_paying_accounts_total']:,} distinct accounts have a recorded SUCCESS payment in the observed period.",
 f"- Observation window: {summary['observation_start']} to {summary['observation_end']}; August is partial.",
 '', '## Findings and treatment', '', '| Issue | Evidence | Business impact | Treatment |','|---|---|---|---|']
for _,r in issues.iterrows(): md.append('| '+' | '.join(str(r[c]).replace('|','\\|') for c in ['issue','evidence','impact','treatment'])+' |')
md += ['', '## Metric caveats','', '- SUCCESS status yields gross recorded cash, not independently reconciled net cash; reversed events cannot be linked with confidence.', '- No currency column is supplied; ₹ interpretation follows the assignment context.', '- Static account DPD/status are not aligned to each event date, so segment cuts are descriptive and can suffer temporal leakage.', '- PTP kept share from labels is 4,489 / (4,489 + 4,553) = 49.65%; payment timing does not independently verify those labels.', '- No single RPC mapping across legacy/v1/v2 disposition versions. No true contact rate is asserted.', '- No client or language fields are available. Agent rows are snapshots; latest updated_at is current-only and not reliable for historical tenure.', '- Costs, historical eligible population, targeting rollout assignment/date, and channel touch-to-payment links are absent; causal ROI and historical no-change counterfactual are not estimable.', '', '## Conclusion','', 'The observed data support a descriptive gross-cash trend after conservative payment normalization. They do not support a validated recovery rate, stable 11% monthly improvement, causal driver attribution, or ₹10 Cr ROI. The next step is a randomized, costed targeting pilot with a fixed denominator and reconciled outcomes.']
(S/'data_quality_report.md').write_text('\n'.join(md),encoding='utf-8')
print(OUT)
